const byPair = new Map(), byJa = new Map();
for (const r of ROWS) { byPair.set(r[0] + '\n' + r[1], r); if (!byJa.has(r[0])) byJa.set(r[0], r); }
const missing = new Set();
// o の中の { ja, en } すべてに、残りの言語を足す（すでにある言語はそのまま）。数字だけなど ja と en が同じ文言は en を写す
function fill(o) {
  if (!o || typeof o !== 'object') return o;
  if (typeof o.ja === 'string' && typeof o.en === 'string') {
    const r = byPair.get(o.ja + '\n' + o.en) || byJa.get(o.ja);
    LANGS.forEach((l, i) => { if (o[l] !== undefined) return; if (r) o[l] = r[i + 2]; else if (o.ja === o.en) o[l] = o.en; else if (!missing.has(o.ja)) { missing.add(o.ja); console.warn('learn_i18n: 訳がありません（ja / en のまま）:', o.ja); } });
    return o;
  }
  for (const k in o) fill(o[k]);
  return o;
}
module.exports = { LANGS, ROWS, LUX_UI, fill, missing };
